<?php get_header(); the_post(); $days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']; $day=kzfr_filter_value('day'); if(!in_array($day,$days,true)) $day=wp_date('l'); $rows=get_option('kzfr_schedule',[]); ?>
<div class="section-wrap section-space"><?php kzfr_page_intro('WEEKLY PROGRAMMING','Schedule','Explore the public weekly schedule. All times are Pacific. Rotating shows share a slot; their week assignments need station confirmation.'); ?><nav class="day-tabs" aria-label="Schedule day"><?php foreach($days as $d): ?><a href="<?php echo esc_url(add_query_arg('day',$d,get_permalink())); ?>" <?php if($day===$d) echo 'aria-current="page"'; ?>><?php echo esc_html($d); ?></a><?php endforeach; ?></nav><div class="schedule-heading"><h2><?php echo esc_html($day); ?></h2><span>Pacific time · schedule checked October 16, 2026</span></div><div class="schedule-list"><?php $count=0; foreach($rows as $row): if(strtolower($row['day'] ?? '')!==strtolower($day))continue; $count++; $slugs=$row['program_slugs'] ?? (isset($row['program_slug']) ? [$row['program_slug']] : []); $titles=$row['program_titles'] ?? (isset($row['program_title']) ? [$row['program_title']] : []); ?><article class="schedule-row"><div class="schedule-time"><?php echo esc_html($row['start'] ?? ''); if(!empty($row['start_day_offset'])) echo ' +1 day'; ?><span>to <?php echo esc_html($row['end'] ?? ''); ?><?php if(!empty($row['end_day_offset'])) echo ' +1 day'; ?></span></div><div><?php foreach($titles as $i=>$title): $program=get_page_by_path($slugs[$i] ?? '',OBJECT,'kzfr_program'); ?><h3><?php if($program): ?><a href="<?php echo esc_url(get_permalink($program)); ?>"><?php echo esc_html($title); ?></a><?php else: echo esc_html($title); endif; ?></h3><?php endforeach; if(!$titles): ?><h3>Program not named in the public schedule</h3><?php endif; if(!empty($row['rotation']) || count($titles)>1): ?><p class="rotation-label">Rotating slot · check KZFR for this week’s program</p><?php endif; if(!empty($row['note'])): ?><p class="small-note"><?php echo esc_html($row['note']); ?></p><?php endif; ?></div></article><?php endforeach; if(!$count): ?><p>No schedule records are available for this day in the preview.</p><?php endif; ?></div><div class="prose schedule-notes"><?php the_content(); ?></div><aside class="source-note"><a href="https://www.kzfr.org/schedule">Check the official station schedule </a>. After-midnight programs appear under the preceding day.</aside></div><?php get_footer(); ?>
